import json
import os
import sys
from settings import export_limit

def select_rows(rows, env):
    limit = export_limit(env)
    selected = rows if limit == 0 else rows[:limit]
    return {"rows": selected, "label": env.get("EXPORT_LABEL", "Batch export")}

if __name__ == "__main__":
    print(json.dumps(select_rows(json.load(sys.stdin), os.environ)))

initial_contents.settings.py:
def export_limit(env):
    raw = env.get("EXPORT_LIMIT", "100")
    limit = int(raw)
    if limit < 0:
        raise ValueError("EXPORT_LIMIT must be nonnegative")
    return limit

