import unittest
from export_app import run_export
from worker import select_rows

class ExportTests(unittest.TestCase):
    def test_default_export_keeps_a_small_batch(self):
        self.assertEqual(run_export([1, 2, 3], {})["rows"], [1, 2, 3])

    def test_export_zero_is_unlimited(self):
        rows = [{"id": number} for number in range(205)]

        result = run_export(rows, {"EXPORT_LIMIT": "0"})

        self.assertEqual(result["rows"], rows)

    def test_worker_zero_is_unlimited(self):
        rows = list(range(205))
        self.assertEqual(select_rows(rows, {"EXPORT_LIMIT": "0"})["rows"], rows)

